css:
@page { size: A4 landscape; margin: 0; }
body { margin: 0; padding: 0; }

.certificate-container {
  position: relative;
  width: 100%;
  min-height: 19cm;
  padding: 2.8cm 3cm;
  background-color: #ffffff;
  color: #0f172a;
  font-family: Helvetica, Arial, sans-serif;
  text-align: center;
  box-sizing: border-box;
  border-top: 12px solid #002B50;
  border-bottom: 12px solid #002B50;
}

.cert-corner {
  position: absolute;
  width: 80px;
  height: 80px;
  border: 2px solid #002B50;
}
.cert-corner-tl { top: 36px;    left: 36px;  border-right: none; border-bottom: none; }
.cert-corner-tr { top: 36px;    right: 36px; border-left:  none; border-bottom: none; }
.cert-corner-bl { bottom: 36px; left: 36px;  border-right: none; border-top:    none; }
.cert-corner-br { bottom: 36px; right: 36px; border-left:  none; border-top:    none; }

.cert-brand { margin-bottom: 1.4cm; }
.cert-brand-logo { height: 48px; width: auto; display: inline-block; }

.cert-eyebrow {
  font-size: 11px;
  letter-spacing: 0.38em;
  text-transform: uppercase;
  color: #64748b;
  font-weight: 600;
}

.cert-rule {
  width: 80px;
  height: 3px;
  background-color: #D70F0A;
  margin: 0.6cm auto 1cm;
}

.cert-presented {
  font-size: 14px;
  color: #64748b;
  letter-spacing: 0.04em;
  margin-bottom: 0.5cm;
}

.cert-name {
  font-family: Georgia, "Times New Roman", serif;
  font-size: 52px;
  font-weight: 400;
  color: #002B50;
  line-height: 1.1;
  margin-bottom: 0.8cm;
  letter-spacing: -0.01em;
}

.cert-body {
  font-size: 14px;
  color: #475569;
  margin-bottom: 0.6cm;
}

.cert-course {
  font-size: 22px;
  font-weight: 700;
  color: #0f172a;
  letter-spacing: -0.01em;
  margin-bottom: 1.6cm;
  max-width: 70%;
  margin-left: auto;
  margin-right: auto;
}

.cert-footer {
  display: table;
  width: 100%;
  margin-top: 0.6cm;
}
.cert-footer-col {
  display: table-cell;
  text-align: left;
  vertical-align: top;
  width: 33.33%;
}
.cert-footer-col-center { text-align: center; }
.cert-footer-col-right  { text-align: right; }

.cert-footer-label {
  font-size: 10px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: #94a3b8;
  font-weight: 600;
  margin-bottom: 4px;
}
.cert-footer-value {
  font-size: 13px;
  color: #0f172a;
  font-weight: 500;
}
.cert-footer-mono {
  font-family: "Courier New", monospace;
  font-size: 11px;
  color: #64748b;
  font-weight: 400;
  letter-spacing: 0.02em;
}

html:
{% set member = frappe.db.get_value("User", doc.member, ["full_name"], as_dict=True) %}
{% set course = frappe.db.get_value("LMS Course", doc.course, ["title", "name", "image"], as_dict=True) %}
{% set instructors = frappe.get_all("Course Instructor", {"parent": doc.course}, pluck="instructor", order_by="idx") %}
{% set instructor_names = [] %}
{% for instructor in instructors %}
  {% set n = frappe.db.get_value("User", instructor, "full_name") %}
  {% if n and n not in instructor_names %}
    {% set _ = instructor_names.append(n) %}
  {% endif %}
{% endfor %}

<meta name="pdfkit-orientation" content="Landscape">
<meta name="pdfkit-load-error-handling" content="ignore">
<meta name="pdfkit-load-media-error-handling" content="ignore">

<div class="certificate-container">
  <div class="cert-corner cert-corner-tl"></div>
  <div class="cert-corner cert-corner-tr"></div>
  <div class="cert-corner cert-corner-bl"></div>
  <div class="cert-corner cert-corner-br"></div>

  <div class="cert-brand">
    <img class="cert-brand-logo" alt="Matchbox" src="data:image/png;base64," />
  </div>

  <div class="cert-eyebrow">Certificate of Completion</div>
  <div class="cert-rule"></div>

  <div class="cert-presented">This certificate is presented to</div>
  <div class="cert-name">{{ member.full_name }}</div>

  <div class="cert-body">for successfully completing the course</div>
  <div class="cert-course">{{ course.title }}</div>

  <div class="cert-footer">
    <div class="cert-footer-col">
      <div class="cert-footer-label">Issued on</div>
      <div class="cert-footer-value">{{ frappe.utils.format_date(doc.issue_date, "long") }}</div>
    </div>
    {% if instructor_names %}
    <div class="cert-footer-col cert-footer-col-center">
      <div class="cert-footer-label">{{ "Instructor" if instructor_names|length == 1 else "Instructors" }}</div>
      <div class="cert-footer-value">{{ instructor_names|join(", ") }}</div>
    </div>
    {% endif %}
    <div class="cert-footer-col cert-footer-col-right">
      <div class="cert-footer-label">Certificate ID</div>
      <div class="cert-footer-value cert-footer-mono">{{ doc.name }}</div>
    </div>
  </div>
</div>
